import json, pickle

with open('/Users/xc/Documents/GitHub/Cigar Picker/data/cigars.json', 'r') as f:
    cigars = json.load(f)

existing = set()
existing_ids = set()
for c in cigars:
    existing.add(c.get('name','').lower().strip())
    existing_ids.add(c.get('id',''))

def exists(name):
    return name.lower().strip() in existing
def id_exists(cid):
    return cid in existing_ids

def make_entry(cid, name, brand, origin, region, wrapper, binder, filler, strength,
               smokingTime, price, rating, flavors, size, length, ringGauge, popularity,
               description, pairings, yearFounded, limited, image=None, buyLinks=None):
    e = {
        "id": cid, "name": name, "brand": brand, "origin": origin, "region": region,
        "wrapper": wrapper, "binder": binder, "filler": filler, "strength": strength,
        "smokingTime": smokingTime, "price": price, "rating": rating, "flavors": flavors,
        "size": size, "length": length, "ringGauge": ringGauge, "popularity": popularity,
        "description": description, "pairings": pairings, "yearFounded": yearFounded,
        "limited": limited,
    }
    if image:
        e["image"] = image
    if buyLinks is None:
        buyLinks = [{"retailer":"Famous Smoke Shop","url":f"https://www.famous-smoke.com/search?q={name.replace(' ','+')}","price":None}]
    e["buyLinks"] = buyLinks
    return e

new_entries = []
seen_names = set()
seen_ids = set()

def add(entry):
    if entry["name"].lower().strip() in existing:
        return False
    if entry["name"].lower().strip() in seen_names:
        return False
    if entry["id"] in existing_ids:
        return False
    if entry["id"] in seen_ids:
        return False
    seen_names.add(entry["name"].lower().strip())
    seen_ids.add(entry["id"])
    new_entries.append(entry)
    return True

